{%- set roles_counts = {} -%}
{%- set total_trials = CTX.form_inputs.keys() | length -%}

{%- for trial, role in CTX.form_inputs.items() -%}
    {%- if roles_counts.get(role) -%}
        {%- do roles_counts.update({role: roles_counts[role] + 1}) -%}
    {%- else -%}
        {%- do roles_counts.update({role: 1}) -%}
    {%- endif -%}
{%- endfor -%}
{{ roles_counts }}

{% set role_counts = {} %}
{% set inverted_data = {"code_architect": [], "auto_mage": [], "task_master": []} %}
{% for trial, role in CTX.form_inputs.items() %}
  {% set count = role_counts.get(role, 0) + 1 %}
  {% do role_counts.update({role: count}) %}
  {% do inverted_data[role].append(trial) %}
{% endfor %}
{% set unique_roles = role_counts.keys()|list %}
{% set max_count = max(role_counts.values()) %}
{% set dominant_roles = [role for role, count in role_counts.items() if count == max_count] %}
{% set other_roles = [role for role, count in role_counts.items() if count < max_count and count > 1] %}
{% set lesser_role = "no" if unique_roles|length == 1 or other_roles|length == 0 else ("hybrid" if dominant_roles|length > 1 else other_roles[0]) %}
{% set lesser_role = "hybrid" if dominant_roles|length > 1 else lesser_role %}
{% set deviations_list = [{"trial": trial, "role_deviation": role} for trial, role in CTX.form_inputs.items() if role_counts[role] == 1] %}
{{ {
    "num_unique_roles": unique_roles|length,
    "max_num_same_role": max_count,
    "pure_role": unique_roles|length == 1,
    "dominant_role": dominant_roles if dominant_roles|length > 1 else dominant_roles[0],
    "lesser_role": lesser_role,
    "deviations_count": deviations_list|length,
    "deviations_list": deviations_list,
    "role_selections_by_trial": {"code_architect": inverted_data["code_architect"],
    "auto_mage": inverted_data["auto_mage"],
    "task_master": inverted_data["task_master"]}
  }
}}

